NEW_PKG = "/mnt/c/dbsvace/vo1/B/task025"

SYMBOLS = ["AAA", "BBB", "CCC"]
ACCOUNTS = ["fund", "desk"]
SIDE = ["BUY", "SELL"]


def load_pkg(root):
