        "engine_version": "0.1.0",
        "price_time_priority": True,
        "trade_id_scheme": "per_symbol_monotonic_from_1",
        "iceberg_replenishment": "tail_of_price_level",
        "self_trade_prevention": "same_account_only",
    }
    if rng.random() < 0.7:
        limits = {}
        for sym in SYMBOLS:
            if rng.random() < 0.6:
                lower = rng.randint(80, 95)
                limits[sym] = {"lower": lower, "upper": rng.randint(lower, 120)}
        config["price_limits"] = limits
    return config


