            p["order_type"] = "MARKET"
            if rng.random() < 0.5:
                p["time_in_force"] = rng.choice(["IOC", "FOK"])
        else:
            p["price"] = price if price is not None else rng.randint(90, 110)
            if ice:
                p["order_type"] = "ICEBERG"
                p["display_quantity"] = rng.randint(1, p["quantity"])
        if account is not None:
            p["account_id"] = account
        return p

    if kind == 0:
        return add(account=rng.choice(ACCOUNTS) if rng.random() < 0.6 else None)
    if kind == 1:
        return add(ice=True)
    if kind == 2:
        return add(market=True)
    if kind == 3:
        oid = rng.choice(sym_orders) if sym_orders and rng.random() < 0.7 else f"o{rng.randrange(1000)}"
        return {"event_id": eid, "type": "CANCEL", "order_id": oid}
    if kind == 4:
        oid = rng.choice(sym_orders) if sym_orders and rng.random() < 0.7 else f"o{rng.randrange(1000)}"
        p = {"event_id": eid, "type": "REPLACE", "order_id": oid,
             "quantity": rng.randint(1, 12), "price": rng.randint(90, 110)}
        if rng.random() < 0.2:
            p["display_quantity"] = rng.randint(1, p["quantity"])
        return p
    if kind == 5:
        return {"event_id": eid, "type": "EXECUTION_REPORT",
                "order_id": rng.choice(sym_orders) if sym_orders and rng.random() < 0.7 else "ghost",
                "benchmark_price": rng.randint(90, 110)}
    if kind == 6:
        return {"event_id": eid, "type": "IMPACT_REPORT",
                "side": rng.choice(SIDE), "quantity": rng.randint(1, 30),
                "benchmark_price": rng.randint(90, 110)}
    if kind == 7:
        marks = {s: rng.randint(90, 110) for s in rng.sample(SYMBOLS, rng.randrange(len(SYMBOLS) + 1))}
        return {"event_id": eid, "type": "PORTFOLIO_REPORT",
                "account_id": rng.choice(ACCOUNTS), "mark_prices": marks}
    if kind == 8:
        known = rng.sample(SYMBOLS, rng.randrange(len(SYMBOLS) + 1))
        marks = {s: rng.randint(90, 110) for s in known}
        scenarios = []
        for nm in rng.sample(["a", "b", "c"], rng.randrange(1, 4)):
            sc = {"name": nm,
                  "prices": {s: rng.randint(90, 110) for s in rng.sample(SYMBOLS, len(known)) if True}
                  if False else {s: rng.randint(90, 110) for s in known}}
            scenarios.append(sc)
        return {"event_id": eid, "type": "PORTFOLIO_STRESS_REPORT",
                "account_id": rng.choice(ACCOUNTS), "mark_prices": marks,
                "scenarios": scenarios}
    if kind == 9:
        return {"event_id": eid, "type": "SESSION_RECONCILIATION",
                "expected_trades": [], "expected_accounts": []}
    if kind in (10, 11, 12):
        alg = {10: "TWAP", 11: "VWAP", 12: "POV"}[kind]
        action = rng.choice(["START", "SLICE", "CANCEL", "REPORT", "VOLUME"])
        pid = f"plan{rng.randrange(6)}"
        if action == "START":
            total = rng.randint(2, 12)
            base = {"event_id": eid, "type": f"{alg}_START", "plan_id": pid,
                    "side": rng.choice(SIDE), "total_quantity": total,
                    "order_type": "MARKET", "benchmark_price": rng.randint(90, 110)}
            if rng.random() < 0.5:
                base["order_type"] = "LIMIT"
                base["price"] = rng.randint(90, 110)
            if alg == "TWAP":
                base["slice_count"] = rng.randint(1, total)
            elif alg == "VWAP":
                base["volume_weights"] = [rng.randint(1, 5) for _ in range(rng.randint(1, 4))]
                base["total_quantity"] = max(total, len(base["volume_weights"]))
            else:
                base["participation_bps"] = rng.choice([1, 1000, 5000, 10000])
            return base
        if action == "VOLUME":
            return {"event_id": eid, "type": "POV_VOLUME", "plan_id": pid,
                    "market_volume_increment": rng.randint(1, 20)}
        return {"event_id": eid, "type": f"{alg}_{action}", "plan_id": pid}
    if kind == 13:
        return {"event_id": eid, "type": "PLAN_TCA_REPORT",
                "plan_id": f"plan{rng.randrange(6)}", "mark_price": rng.randint(90, 110)}
    if kind == 14:
        return {"event_id": eid, "type": "BOOK_RECONSTRUCTION_REPORT",
                "target_sequence": rng.randrange(0, 40)}
    return {"event_id": eid, "type": "PRICE_LIMIT_UPDATE",
            "lower_price": rng.randint(80, 95), "upper_price": rng.randint(100, 120)}


def malformed(rng, eid):
    choice = rng.randrange(8)
    if choice == 0:
        return {"event_id": eid, "type": "ADD", "order_id": "z", "side": "BAD",
                "order_type": "MARKET", "quantity": 1}
    if choice == 1:
        return {"event_id": eid, "type": "IMPACT_REPORT", "side": "BUY",
                "quantity": -2, "benchmark_price": 100}
    if choice == 2:
        return {"event_id": eid, "type": "NOPE"}
    if choice == 3:
        return {"event_id": eid, "type": "IMPACT_REPORT", "side": "BUY",
                "quantity": True, "benchmark_price": 100}
    if choice == 4:
        return {"event_id": eid, "type": "TWAP_SLICE"}
    if choice == 5:
        return {"event_id": eid, "type": "PRICE_LIMIT_UPDATE",
                "lower_price": 100, "upper_price": 90}
    if choice == 6:
        return {"event_id": "", "type": "IMPACT_REPORT", "side": "BUY",
                "quantity": 1, "benchmark_price": 100}
    return {"event_id": eid, "type": "IMPACT_REPORT", "side": "BUY",
            "quantity": 1, "benchmark_price": 100, "rogue": 1}


def build_stream(rng):
    state = {s: {"orders": [], "plans": [], "seq": 0} for s in SYMBOLS}
    events = []
    emitted = []
    n = rng.randint(30, 90)
    for i in range(n):
        roll = rng.random()
        if roll < 0.08 and emitted:
            # exact retry of an earlier event (stale sequence -> DUPLICATE)
            events.append(copy.deepcopy(rng.choice(emitted)))
            continue
        if roll < 0.12 and emitted:
            # same event id, conflicting payload on a (possibly other) symbol
            src = copy.deepcopy(rng.choice(emitted))
            src["type"] = "IMPACT_REPORT"
            src["side"] = "BUY"
            src["quantity"] = 1
            src["benchmark_price"] = 99
            for k in ("order_id", "plan_id", "mark_prices", "scenarios",
                      "account_id", "expected_trades", "expected_accounts",
                      "target_sequence", "lower_price", "upper_price",
                      "order_type", "price", "total_quantity", "slice_count",
                      "volume_weights", "participation_bps",
                      "market_volume_increment"):
                src.pop(k, None)
            events.append(src)
            continue
        sym = rng.choice(SYMBOLS)
        st = state[sym]
        eid = f"e{len(emitted)}"
        if roll < 0.18:
            payload = malformed(rng, eid)
            seq = rng.choice([st["seq"] + 1, st["seq"] + 3, max(1, st["seq"])])
        else:
            payload = valid_payload(rng, eid, st)
            if payload["type"] == "ADD":
                st["orders"].append(payload["order_id"])
            if payload["type"].endswith("_START"):
                st["plans"].append(payload["plan_id"])
            r = rng.random()
            if r < 0.06:
                seq = max(1, st["seq"])            # stale/out-of-order
            elif r < 0.10:
                seq = st["seq"] + rng.randint(2, 4)  # gap
            else:
                st["seq"] += 1
                seq = st["seq"]
        ev = {"event_id": eid, "symbol": sym, "sequence": seq}
        ev.update(payload)
        if rng.random() < 0.2:
            ev["timestamp"] = rng.choice([rng.randint(0, 10 ** 9), "2026-01-01T00:00:00Z"])
        events.append(ev)
        emitted.append(ev)
    return events


def canon(mod, value):
    return mod.canonical_json(value)


def main():
    ref = load_pkg(HEAD_PKG)
    new = load_pkg(NEW_PKG)
    failures = 0
    for seed in range(120):
        rng = random.Random(seed)
        config = make_config(rng)
        events = build_stream(rng)
        cut = rng.randrange(0, len(events) + 1)

        try:
            ref_one = ref.replay_events(copy.deepcopy(events), config=copy.deepcopy(config))
        except Exception as exc:  # noqa: BLE001
            ref_one = ("EXC", type(exc).__name__, str(exc), getattr(exc, "code", None))
        try:
            new_one = new.replay_events(copy.deepcopy(events), config=copy.deepcopy(config))
        except Exception as exc:  # noqa: BLE001
            new_one = ("EXC", type(exc).__name__, str(exc), getattr(exc, "code", None))

        ref_bytes = canon(ref, ref_one) if not isinstance(ref_one, tuple) else json.dumps(ref_one).encode()
        new_bytes = canon(new, new_one) if not isinstance(new_one, tuple) else json.dumps(new_one).encode()
        if ref_bytes != new_bytes:
            failures += 1
            print(f"seed {seed}: ONE-SHOT MISMATCH")
            # show first differing result
            if not isinstance(ref_one, tuple) and not isinstance(new_one, tuple):
                for idx, (a, b) in enumerate(zip(ref_one["results"], new_one["results"])):
                    if canon(ref, a) != canon(new, b):
                        print("  idx", idx)
                        print("  ref:", canon(ref, a).decode()[:400])
                        print("  new:", canon(new, b).decode()[:400])
                        break
            if failures >= 5:
                break
            continue

        if isinstance(ref_one, tuple):
            continue

        # snapshot prefix must be byte identical
        try:
            ref_pre = ref.replay_events(copy.deepcopy(events[:cut]), config=copy.deepcopy(config))
            new_pre = new.replay_events(copy.deepcopy(events[:cut]), config=copy.deepcopy(config))
        except Exception:  # noqa: BLE001
            continue
        if canon(ref, ref_pre["snapshot"]) != canon(new, new_pre["snapshot"]):
            failures += 1
            print(f"seed {seed}: PREFIX SNAPSHOT MISMATCH at cut {cut}")
            if failures >= 5:
                break
            continue

        # resume tail from each side's own snapshot
        ref_tail = ref.replay_events(copy.deepcopy(events[cut:]),
                                     config=copy.deepcopy(config),
                                     snapshot=copy.deepcopy(ref_pre["snapshot"]),
                                     snapshot_after=None)
        new_tail = new.replay_events(copy.deepcopy(events[cut:]),
                                     config=copy.deepcopy(config),
                                     snapshot=copy.deepcopy(new_pre["snapshot"]),
                                     snapshot_after=None)
        if canon(ref, ref_tail["results"]) != canon(new, new_tail["results"]):
            failures += 1
            print(f"seed {seed}: RESUME-TAIL MISMATCH at cut {cut}")
            if failures >= 5:
                break
            continue

        # cross-feed: new snapshot restored by ref and vice versa
        try:
            cross_a = ref.replay_events(copy.deepcopy(events[cut:]),
                                        config=copy.deepcopy(config),
                                        snapshot=copy.deepcopy(new_pre["snapshot"]),
                                        snapshot_after=None)
            cross_b = new.replay_events(copy.deepcopy(events[cut:]),
                                        config=copy.deepcopy(config),
                                        snapshot=copy.deepcopy(ref_pre["snapshot"]),
                                        snapshot_after=None)
            if canon(ref, cross_a["results"]) != canon(ref, ref_tail["results"]):
                failures += 1
                print(f"seed {seed}: CROSS-FEED new->ref mismatch")
                if failures >= 5:
                    break
                continue
            if canon(new, cross_b["results"]) != canon(new, new_tail["results"]):
                failures += 1
                print(f"seed {seed}: CROSS-FEED ref->new mismatch")
                if failures >= 5:
                    break
                continue
        except Exception as exc:  # noqa: BLE001
            failures += 1
            print(f"seed {seed}: CROSS-FEED raised {type(exc).__name__}: {exc}")
            if failures >= 5:
                break
            continue

    print("OK" if failures == 0 else f"{failures} FAILURES")
    return failures


if __name__ == "__main__":
    sys.exit(1 if main() else 0)

